/// Computes the triangular number of a given non-negative integer n.
fn triangle(n: u32) -> u32 {
    // The triangular number can be computed using the formula n * (n + 1) / 2
    n * (n + 1) / 2
}

/// Proves that the triangular number function is monotonic:
/// If i ≤ j, then triangle(i) ≤ triangle(j).
fn triangle_is_monotonic(i: u32, j: u32) -> bool {
    if i <= j {
        triangle(i) <= triangle(j)
    } else {
        true // This case is not relevant since we assume i ≤ j
    }
}

/// Tail-recursive procedure to compute the triangular number of a target n,
/// starting from the current index idx and accumulating the result in sum.
fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    if idx < n {
        *sum += idx + 1; // Add the next number to the sum
        tail_triangle(n, idx + 1, sum); // Recur with the next index
    }
}

